#include <immintrin.h>
#include <cstddef>

// Auto-vectorizable: contiguous, no aliasing (__restrict), no branches.
void scale_add(float* __restrict out,
               const float* __restrict a,
               const float* __restrict b,
               float k, size_t n) {
    for (size_t i = 0; i < n; ++i)
        out[i] = a[i] * k + b[i];     // -O3 -march=native -> FMA over 8 lanes
}

// Explicit AVX2 version of the same kernel (8 floats per iteration).
void scale_add_avx2(float* out, const float* a, const float* b,
                    float k, size_t n) {
    __m256 vk = _mm256_set1_ps(k);
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        __m256 va = _mm256_loadu_ps(a + i);
        __m256 vb = _mm256_loadu_ps(b + i);
        __m256 vo = _mm256_fmadd_ps(va, vk, vb);   // a*k + b, 8 lanes
        _mm256_storeu_ps(out + i, vo);
    }
    for (; i < n; ++i) out[i] = a[i] * k + b[i];   // scalar tail
}

#include <immintrin.h>

// out[i] = (a[i] > thr) ? a[i] : 0, vectorized with a mask (no per-lane branch).
void keep_above(float* out, const float* a, float thr, int n) {
    __m256 vthr = _mm256_set1_ps(thr);
    __m256 zero = _mm256_setzero_ps();
    int i = 0;
    for (; i + 8 <= n; i += 8) {
        __m256 va   = _mm256_loadu_ps(a + i);
        __m256 mask = _mm256_cmp_ps(va, vthr, _CMP_GT_OQ);  // per-lane 0/-1
        __m256 vo   = _mm256_blendv_ps(zero, va, mask);     // select per lane
        _mm256_storeu_ps(out + i, vo);
    }
    for (; i < n; ++i) out[i] = a[i] > thr ? a[i] : 0.f;
}

#include <immintrin.h>
#include <vector>

void mid_soa(float* __restrict mid, const float* __restrict bid,
             const float* __restrict ask, int n) {
    __m256 half = _mm256_set1_ps(0.5f);
    int i = 0;
    for (; i + 8 <= n; i += 8) {
        __m256 b = _mm256_loadu_ps(bid + i);
        __m256 a = _mm256_loadu_ps(ask + i);
        _mm256_storeu_ps(mid + i, _mm256_mul_ps(half, _mm256_add_ps(b, a)));
    }
    for (; i < n; ++i) mid[i] = 0.5f * (bid[i] + ask[i]);
}

#include <immintrin.h>
#include <vector>

// SoA layout enables a clean FMA reduction with multiple accumulators.
double notional(const std::vector<double>& qty, const std::vector<double>& price) {
    size_t n = qty.size(), i = 0;
    __m256d acc0 = _mm256_setzero_pd(), acc1 = _mm256_setzero_pd();
    for (; i + 8 <= n; i += 8) {
        acc0 = _mm256_fmadd_pd(_mm256_loadu_pd(&qty[i]),   _mm256_loadu_pd(&price[i]),   acc0);
        acc1 = _mm256_fmadd_pd(_mm256_loadu_pd(&qty[i+4]), _mm256_loadu_pd(&price[i+4]), acc1);
    }
    __m256d acc = _mm256_add_pd(acc0, acc1);
    double tmp[4]; _mm256_storeu_pd(tmp, acc);
    double s = tmp[0]+tmp[1]+tmp[2]+tmp[3];
    for (; i < n; ++i) s += qty[i]*price[i];   // scalar tail
    return s;
}
